#pragma once
#include "runtime_paths.hpp"
namespace uw::runtime {
inline std::vector<wchar_t> childEnvironment(const Layout&layout){std::vector<std::wstring>values;auto*block=GetEnvironmentStringsW();if(block){for(auto*p=block;*p;p+=wcslen(p)+1)values.emplace_back(p);FreeEnvironmentStringsW(block);}std::vector<std::wstring>dirs;if(!layout.host.empty())dirs.push_back(layout.host.parent_path().wstring());dirs.push_back(layout.backendDir.wstring());return environment(values,dirs,layout.host.wstring());}
struct HostProbe{bool attempted=false,launched=false,exited=false;DWORD error=0,exitCode=STILL_ACTIVE;const char*stage="not attempted";};
inline HostProbe probeHost(const Layout&layout,std::vector<wchar_t>&environment){HostProbe result;if(layout.host.empty())return result;result.attempted=true;result.stage="prepare probe";SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};HANDLE nul=CreateFileW(L"NUL",GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,&sa,OPEN_EXISTING,0,nullptr);HANDLE job=CreateJobObjectW(nullptr,nullptr);if(!job){result.error=GetLastError();if(nul!=INVALID_HANDLE_VALUE)CloseHandle(nul);return result;}JOBOBJECT_EXTENDED_LIMIT_INFORMATION limit{};limit.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;if(!SetInformationJobObject(job,JobObjectExtendedLimitInformation,&limit,sizeof(limit))){result.error=GetLastError();CloseHandle(job);if(nul!=INVALID_HANDLE_VALUE)CloseHandle(nul);return result;}
 STARTUPINFOW si{};si.cb=sizeof(si);si.dwFlags=STARTF_USESTDHANDLES|STARTF_USESHOWWINDOW;si.wShowWindow=SW_HIDE;si.hStdInput=si.hStdOutput=si.hStdError=nul;PROCESS_INFORMATION pi{};std::wstring command=L"\""+layout.host.wstring()+L"\" --help";auto cwd=layout.host.parent_path();result.stage="CreateProcess";BOOL ok=CreateProcessW(layout.host.c_str(),command.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW|CREATE_SUSPENDED|CREATE_UNICODE_ENVIRONMENT,environment.data(),cwd.c_str(),&si,&pi);result.error=ok?0:GetLastError();if(nul!=INVALID_HANDLE_VALUE)CloseHandle(nul);if(!ok){CloseHandle(job);return result;}result.launched=true;result.stage="job assignment";if(!AssignProcessToJobObject(job,pi.hProcess)){result.error=GetLastError();TerminateProcess(pi.hProcess,1);}else if(ResumeThread(pi.hThread)==(DWORD)-1){result.error=GetLastError();TerminateProcess(pi.hProcess,1);}else{result.stage="help process";result.exited=WaitForSingleObject(pi.hProcess,1500)==WAIT_OBJECT_0;if(result.exited)GetExitCodeProcess(pi.hProcess,&result.exitCode);}CloseHandle(job);WaitForSingleObject(pi.hProcess,500);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);return result;}
inline std::wstring privatePath(const std::wstring&path){DWORD size=GetEnvironmentVariableW(L"USERPROFILE",nullptr,0);if(size&&size<32768){std::wstring profile(size,L'\0');GetEnvironmentVariableW(L"USERPROFILE",profile.data(),size);profile.resize(wcslen(profile.c_str()));if(!profile.empty()&&path.size()>=profile.size()&&_wcsnicmp(profile.c_str(),path.c_str(),profile.size())==0&&(path.size()==profile.size()||path[profile.size()]==L'\\'||path[profile.size()]==L'/'))return L"<USERPROFILE>"+path.substr(profile.size());}return path;}
}
